const news=[
 {date:'29 Eylül 2026',tag:'AI modelleri',title:'OpenAI, GPT‑6.1 Sol modelini duyurdu',body:'OpenAI’nin model ailesindeki yeni sürüm ve önceki GPT‑6 duyurusuna eklenen güncellemeler. Modelin kodlama kullanımındaki etkisini kaynak duyurudaki kapsam ve erişilebilirlik ayrıntılarıyla değerlendirin.',summary:'Kaynak, GPT‑6 ailesinin Sol ve Luna modellerinin tanıtımını ve 29 Eylül tarihli güncelleme notunu içeriyor. Bu kart duyuruyu özetler; yetenek ve erişim ayrıntıları için kaynak metni kontrol edin.',source:sources.openai,kind:'Resmi duyuru'},
 {date:'14 Eylül 2026',tag:'Kubernetes',title:'Kubernetes v1.37: Memory QoS Beta aşamasına geçti',body:'Kubernetes blogu Memory QoS özelliğinin v1.37 ile Beta’ya alındığını ve Linux cgroup v2 sistemlerinde varsayılan olarak etkinleştiğini açıklıyor.',summary:'Pod düzeyindeki bellek hizmet kalitesi desteği Beta aşamasında. v1.37 kubelet’lerinde özellik varsayılan açık olsa da varsayılan yapılandırma throttling veya reservation değerlerini kendiliğinden yazmıyor. Mevcut kümelerde davranışı sürüm notları ve yapılandırma üzerinden doğrulayın.',source:sources.kubeNews,kind:'Proje blogu'},
 {date:'3 Eylül 2026',tag:'GitHub Actions',title:'Actions için runner API ve token izinleri güncellendi',body:'GitHub, runner sürüm sonu bilgilerini sorgulayan REST API’yi ve GITHUB_TOKEN için salt okunur vulnerability-alerts iznini duyurdu.',summary:'Runner yaşam döngüsünü önceden planlamak ve workflow token’ına Dependabot uyarıları için gereken en az izni vermek kolaylaşıyor. Kullanırken güncel API ve izin dokümanına bakın.',source:sources.github,kind:'Resmi changelog'}
];
const concepts=[
 {id:'clr',type:'.NET çalışma zamanı',name:'CLR nedir?',desc:'C# kodunun çalıştırılmasına ve yönetilen bellek gibi hizmetlere aracılık eden .NET çalışma zamanı.',body:'CLR (Common Language Runtime), .NET için kodu çalıştıran ve yönetilen yürütme hizmetleri sağlayan çalışma ortamıdır. C# derleyicisi genellikle kaynak kodu IL ve metadata içeren bir assembly’ye dönüştürür; runtime bunu yükleyip çalıştırır. CLR, garbage collection gibi hizmetlere de katkı verir.',analogy:'Bir benzetme: C# derleyicisi tarifini ortak bir ara dile çevirir; CLR bu tarifi makinede çalıştırıp yürütme sırasında gerekli hizmetleri sağlar. Benzetme yalnızca akışı anlatır; teknik ayrıntıların tamamı değildir.',source:sources.clr},
 {id:'ddd',type:'Yazılım tasarımı',name:'Domain-Driven Design',desc:'Karmaşık iş alanını anlamayı ve modelini yazılım tasarımının merkezine koymayı öneren yaklaşım.',body:'Domain-Driven Design (DDD), yazılım tasarımında iş alanını (domain) anlamaya ve alan uzmanlarıyla ortak bir dil kurmaya odaklanır. Bounded context gibi araçlar, aynı terimin farklı alt alanlarda farklı anlam taşıyabileceğini görünür kılar. Her projeye DDD uygulamak gerekmez; karmaşık iş kurallarında daha yararlıdır.',analogy:'E-ticarette “sipariş” ödeme, depo ve kargo ekipleri için farklı kurallara sahip olabilir. Her bağlamın modelini ayrı ve açık tutmak, tek bir dev modelde anlamların karışmasını önler.',source:{label:'Martin Fowler · DDD',url:'https://martinfowler.com/bliki/DomainDrivenDesign.html'}},
 {id:'k8s',type:'Operasyon',name:'Kubernetes ne yapar?',desc:'Konteynerleştirilmiş iş yüklerini küme üzerinde tanımlı istenen duruma göre yönetir.',body:'Kubernetes, konteynerleştirilmiş uygulamaları küme üzerinde dağıtmak ve yönetmek için bir platformdur. Kullanıcı nesnelerle istenen durumu bildirir; kontrol döngüleri bu duruma yaklaşmaya çalışır. Pod temel çalıştırma birimidir. Kubernetes, uygulama kodunun yerine geçmez ve tek başına her altyapı sorununu çözmez.',analogy:'Bir orkestratör gibi düşünebilirsin: kaç uygulama kopyası istediğini söylersin; küme denetleyicileri uygun düğümlerde çalışır durumda tutmaya çalışır.',source:sources.kubernetes},
 {id:'ddl',type:'Veritabanı',name:'DDL nedir?',desc:'Tablo ve şema gibi veritabanı nesnelerinin yapısını tanımlayan SQL komutları.',body:'DDL (Data Definition Language), veritabanı nesnelerinin yapısını tanımlayan SQL komutları için kullanılan terimdir. PostgreSQL dokümantasyonundaki CREATE, ALTER ve DROP komutları tablo ve diğer nesneleri oluşturur, değiştirir veya kaldırır. DDL sınıflandırmalarının sınırları veritabanına göre değişebilir.',analogy:'Bir uygulamanın içindeki kayıtları doldurmadan önce hangi tablo ve sütunların var olacağını tanımlamak, DDL’nin tipik kullanım alanıdır.',source:sources.ddl},
 {id:'aspire',type:'.NET araçları',name:'.NET Aspire',desc:'Dağıtık uygulamaların servislerini, bağımlılıklarını ve yerel gözlemlenebilirliğini kodla modellemeye yarar.',body:'.NET Aspire, dağıtık uygulamalar için kodla tanımlanan orkestrasyon ve gözlemlenebilirlik katmanıdır. AppHost içinde servisler, veritabanları ve diğer kaynaklar modellenebilir; geliştirme sırasında bunları birlikte başlatıp Aspire Dashboard’da izlemeye yardımcı olur. Aspire bir uygulama framework’ünün veya üretim ortamının kendisi değildir.',analogy:'API, web arayüzü, veritabanı ve önbelleği her seferinde ayrı terminallerden başlatmak yerine, geliştirme ortamındaki bu kaynakları tek bir uygulama modeli içinde ifade etmeye yardım eder.',source:sources.aspire}
];
const conceptCard=(id,type,name,desc,body,analogy,url,label)=>({id,type,name,desc,body,analogy,source:{label,url}});
const expandedConcepts=[
 conceptCard('frontend','Temel kavram','Front-end nedir?','Kullanıcının tarayıcıda veya uygulamada gördüğü ve etkileştiği arayüz katmanı.','Front-end; arayüzü çizme, kullanıcı girdilerini alma, erişilebilirlik ve sunucuyla iletişim gibi işleri kapsar. Web’de HTML, CSS ve JavaScript sık kullanılır. Hassas sırlar veya güvenilir yetki kontrolleri tarayıcı koduna emanet edilmez.','Bir mağazanın ürün sayfası, sepeti ve butonları arayüzün görünen kısmıdır.','https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content','MDN Web Docs'),
 conceptCard('backend','Temel kavram','Back-end nedir?','İstekleri işleyen, iş kurallarını uygulayan ve kalıcı veriye erişen sunucu tarafı.','Back-end; HTTP isteklerini doğrulayıp işler, yetkilendirme ve iş kurallarını uygular, veritabanı veya diğer servislerle konuşur. Uygulamanın güvenlik sınırıdır; istemciden gelen veriye güvenilmez.','Siparişi oluşturma ve stok yeterli mi diye kontrol etme, sunucu tarafındaki iş kurallarına örnektir.','https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side','MDN Web Docs'),
 conceptCard('fullstack','Temel kavram','Full-stack ne demek?','Bir ürünün istemci ve sunucu katmanları arasında uçtan uca çalışabilmek.','Full-stack, front-end ve back-end konularında birlikte çalışabilmeyi anlatır; her teknolojide uzman olmak demek değildir. Veri akışı, API sözleşmesi, hata ayıklama, test ve dağıtım sınırlarını anlayabilmek önemlidir.','Bir formdan başlayan isteği, API doğrulamasını ve veritabanı kaydını takip edip kullanıcıya sonucu göstermek.','https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side','MDN Web Docs'),
 conceptCard('dom','Web temeli','DOM nedir?','HTML belgesinin programlarla okunup güncellenebilen ağaç biçimli temsili.','DOM (Document Object Model), tarayıcının belgeyi düğümlerden oluşan bir nesne ağacı olarak sunan API’sidir. JavaScript DOM’u okuyup değiştirebilir; React gibi kütüphaneler arayüz güncellemelerini kendi render modeliyle yönetir.','Bir başlığı değiştirmek, DOM ağacındaki ilgili öğenin metnini güncellemektir.','https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model','MDN Web Docs'),
 conceptCard('api','Web temeli','API nedir?','Yazılımların belirli kurallarla birbirinden işlem veya veri istemesini sağlayan arayüz.','API, bir sistemin sunduğu işlemleri ve bunların girdi/çıktı sözleşmesini tanımlar. HTTP API’leri metotlar, yollar, başlıklar, gövdeler ve durum kodları kullanabilir. API yalnızca web servisi anlamına gelmez.','Bir restoran menüsü hangi yemeklerin istenebileceğini ve sipariş biçimini tanımlar; API de benzer biçimde kullanılabilir işlemleri açıklar.','https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Introduction','MDN Web Docs'),
 conceptCard('http','Ağ ve web','HTTP request/response','İstemcinin istek gönderip sunucunun durum kodu, başlıklar ve içerikle yanıt vermesi.','HTTP bir uygulama katmanı iletişim protokolüdür. İstek metot, hedef, başlıklar ve isteğe bağlı gövdeden; yanıt durum kodu, başlıklar ve isteğe bağlı gövdeden oluşur. HTTP kendi başına şifreleme sağlamaz.','Tarayıcı GET /products isteği yollar; sunucu 200 ve JSON yanıtı gönderebilir.','https://developer.mozilla.org/en-US/docs/Web/HTTP/Overview','MDN Web Docs'),
 conceptCard('https','Ağ ve web','HTTPS ve TLS','HTTP iletişimini TLS ile koruyarak aktarım sırasında gizlilik ve bütünlük sağlayan bağlantı.','HTTPS, HTTP’nin TLS ile taşınmasıdır. TLS bağlantısı sunucunun sertifikasını doğrular ve ağ üzerinden giden veriyi şifreler. HTTPS, uygulamanın kendisini veya veritabanını otomatik olarak güvenli yapmaz.','HTTPS halka açık Wi‑Fi’da yol üzerindeki kişilerin sayfa isteğinin içeriğini kolayca okuyup değiştirmesini engellemeye yardımcı olur.','https://developer.mozilla.org/en-US/docs/Glossary/HTTPS','MDN Web Docs'),
 conceptCard('json','Veri biçimleri','JSON nedir?','Sistemler arasında yapılandırılmış veriyi taşımak için kullanılan metin biçimi.','JSON; nesne, dizi, metin, sayı, boolean ve null değerlerini temsil eden dil bağımsız bir veri biçimidir. JSON metni tipli bir JavaScript nesnesi değildir; parse edilip doğrulanması gerekir.','API, kullanıcı profilini {"name":"Ada"} biçiminde gönderebilir.','https://www.rfc-editor.org/rfc/rfc8259','IETF RFC 8259'),
 conceptCard('xml','Veri biçimleri','XML nedir?','Etiketlerle hiyerarşik veriyi tanımlayan metin biçimi.','XML, öğeler, nitelikler ve metin içeriğiyle yapılandırılmış belgeleri temsil eder. Şema doğrulama, ad alanları ve mevcut sistem uyumluluğu gereken entegrasyonlarda hâlâ kullanılır.','Bir yapılandırma belgesinde <service name="api"> gibi etiketler öğe ve niteliği ayırır.','https://www.w3.org/TR/xml/','W3C XML'),
 conceptCard('cache','Performans','Cache / önbellek','Tekrar gereken veriyi daha hızlı erişim için geçici tutan katman.','Önbellek tarayıcıda, CDN’de, uygulama belleğinde veya ayrı bir serviste olabilir. Hız kazandırır; fakat süresi, geçersiz kılma ve tutarlılık politikası tasarlanmalıdır. Eski veri görme ve cache stampede gibi riskleri vardır.','Bir ürün görselini her ziyarette yeniden indirmek yerine tarayıcı önbelleğinden almak.','https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching','MDN Web Docs'),
 conceptCard('env-vars','Dağıtım','Environment variable nedir?','Program yapılandırmasını koddan ve dağıtım ortamından ayıran isim-değer girdisi.','Ortam değişkenleri uygulamaya süreç ortamından aktarılır. Ortam ayrımı ve sır yapılandırması için kullanılabilirler; ancak sırları loglara yazmamak, erişimi sınırlamak ve uygun secret yönetimi kullanmak gerekir.','API anahtarını depoya commit etmek yerine gizli yapılandırmadan okumak.','https://12factor.net/config','The Twelve-Factor App'),
 conceptCard('cli','Geliştirici araçları','CLI nedir?','İşletim sistemine veya araca metin komutlarıyla işlem yaptıran arayüz.','Command-line interface (CLI), komut ve argümanlarla araç çalıştırmayı sağlar. Komutları betiklemek tekrarlanabilirlik sağlar; önce çalışılan dizin ve hedef üzerinde etkisi anlaşılmalıdır.','git status depodaki çalışma ağacını gösterir; npm test proje test komutunu çalıştırır.','https://git-scm.com/docs/git','Git Documentation'),
 conceptCard('database','Veri','Veritabanı nedir?','Veriyi kalıcı biçimde düzenleyen, sorgulayan ve güncelleyen sistem.','Veritabanı yalnızca dosya veya tablo değildir; veri modeli, sorgu dili, eşzamanlılık ve dayanıklılık mekanizmaları olan bir sistemdir. İlişkisel ve belge/tabanlı gibi farklı modeller iş yüküne göre seçilir.','Bir kullanıcı hesabı ve ilişkili siparişler kalıcı veritabanında saklanabilir.','https://www.postgresql.org/docs/current/tutorial.html','PostgreSQL Docs'),
 conceptCard('sql-ddl','Veri','DDL ve DML farkı','DDL şema yapısını, DML ise bu yapılardaki kayıtlarla yapılan işlemleri ifade eder.','DDL terimi CREATE, ALTER ve DROP gibi şema/nesne tanımlama komutlarını kapsar. DML ise INSERT, UPDATE ve DELETE gibi veri değiştirme komutları için kullanılır; sınıflandırmanın sınırı kaynaklara göre değişebilir.','Tabloyu CREATE TABLE ile kurmak DDL; satır eklemek INSERT ile DML örneğidir.','https://www.postgresql.org/docs/current/ddl.html','PostgreSQL Docs'),
 conceptCard('relational-db','Veri','İlişkisel veritabanı','Veriyi tanımlı şemalara sahip tablolarda tutup SQL ile ilişkilendiren model.','İlişkisel veritabanları satır ve sütunlara, anahtarlara ve kısıtlara dayanır. Foreign key ilişkileri ve transaction’lar veri tutarlılığına yardımcı olur. MySQL ve PostgreSQL örneklerdir.','orders.customer_id ile customers.id arasında foreign key ilişkisi kurmak.','https://www.postgresql.org/docs/current/tutorial-fk.html','PostgreSQL Docs'),
 conceptCard('nosql','Veri','NoSQL ne anlama gelir?','İlişkisel olmayan veri modelleri için kullanılan geniş bir kategori.','NoSQL, tek bir teknoloji veya SQL’in tamamen olmadığı anlamına gelmez. Belge, anahtar-değer, kolon ailesi ve graf gibi modelleri kapsar. Sorgu ve tutarlılık özellikleri ürüne göre değişir.','MongoDB belge odaklı; Redis anahtar-değer; Neo4j graf modeline örnektir.','https://www.mongodb.com/docs/manual/introduction/','MongoDB Docs'),
 conceptCard('ui-ux','Ürün tasarımı','UI ve UX farkı','UI arayüz öğelerine; UX ise ürünle yaşanan uçtan uca deneyime odaklanır.','UI (User Interface), kullanıcının etkileştiği görsel ve işlevsel kontrolleri kapsar. UX (User Experience), ürünü keşfetme, kullanma ve hedefine ulaşma deneyiminin bütünüdür; yalnızca görünüş veya estetik değildir.','Butonun görünümü UI; doğru işlemi bulmanın ve tamamlamanın kolaylığı UX boyutudur.','https://www.nngroup.com/articles/definition-user-experience/','Nielsen Norman Group'),
 conceptCard('responsive','Web tasarımı','Responsive tasarım','Arayüzün ekran ölçüsü ve kullanım koşullarına göre uyumlu düzenlenmesi.','Responsive Web Design; esnek ızgara, esnek medya ve CSS medya sorgularıyla farklı genişliklerde kullanılabilir düzen oluşturur. Mobilde yalnızca küçültmek yeterli değildir; içerik hiyerarşisi ve erişilebilir etkileşimler de korunmalıdır.','Dar ekranda yan menünün açılır gezinmeye dönüşmesi.','https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout/Responsive_Design','MDN Web Docs'),
 conceptCard('cors','Ağ ve güvenlik','CORS nedir?','Tarayıcının farklı origin’den gelen web sayfası betiklerine uyguladığı paylaşım denetimi.','CORS (Cross-Origin Resource Sharing), sunucunun belirli origin’lerden tarayıcı koduna yanıtı açmasına yarayan HTTP başlıkları mekanizmasıdır. CORS kimlik doğrulama veya sunucu tarafı erişim kontrolünün yerine geçmez.','https://api.example.com, Access-Control-Allow-Origin ile izin verilen web origin’ini bildirir.','https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS','MDN Web Docs'),
 conceptCard('encryption','Güvenlik','Şifreleme ve çözme','Şifreleme veriyi anahtarla korur; çözme, uygun anahtarla okunabilir biçime geri getirir.','Simetrik şifrelemede aynı gizli anahtar kullanılır; asimetrik şifrelemede anahtar çifti bulunur. Hashing tek yönlü özet üretir ve şifre çözme değildir. Anahtar yönetimi güvenliğin temel parçasıdır.','TLS, bağlantı kurulumunda asimetrik ve simetrik kriptografiyi farklı amaçlarla bir araya getirir.','https://csrc.nist.gov/glossary/term/encryption','NIST'),
 conceptCard('ip-address','Ağ','IP adresi ve DNS','IP adresi ağ arayüzlerine yönlendirme adresi verir; DNS adları adres kayıtlarına çözer.','IPv4 32 bit, IPv6 128 bit adresleme kullanır. IP adresi cihazın değişmez kimliği değildir; NAT, DHCP ve bulut ağları nedeniyle değişebilir. DNS ise alan adlarını IP gibi kayıtlara eşler.','Tarayıcı example.com adına DNS sorgusu yapar, sonra elde ettiği adrese bağlantı kurar.','https://www.cloudflare.com/learning/dns/glossary/what-is-my-ip-address/','Cloudflare Learning Center'),
 conceptCard('proxy','Ağ','Proxy ve reverse proxy','Proxy istemci adına hedefe; reverse proxy ise sunucu/servisler önünde istemciler adına istek iletir.','Forward proxy genellikle istemci tarafında, reverse proxy uygulama sunucularının önünde konumlanır. Reverse proxy TLS sonlandırma, yönlendirme ve yük dağıtma yapabilir; tek başına VPN veya güvenlik garantisi değildir.','Nginx reverse proxy /api isteklerini uygulama sunucusuna yönlendirebilir.','https://developer.mozilla.org/en-US/docs/Web/HTTP/Proxy_servers_and_tunneling','MDN Web Docs'),
 conceptCard('firewall','Ağ ve güvenlik','Firewall nedir?','Ağ trafiğini tanımlanmış kurallara göre izinleyen veya engelleyen kontrol katmanı.','Firewall ağ, ana makine veya bulut uygulama katmanında çalışabilir. Kural kapsamı, yönü ve varsayılan davranışı açık olmalıdır. Firewall, uygulamadaki kimlik doğrulamanın yerini tutmaz.','Bulut güvenlik grubu yalnızca gerekli uygulama portuna erişim izni verebilir.','https://docs.aws.amazon.com/vpc/latest/userguide/vpc-security-groups.html','AWS Documentation'),
 conceptCard('serverless','Bulut','Serverless ne demek?','Sunucu altyapısının sağlayıcı tarafından yönetildiği, kodun olay veya istekle çalıştırıldığı model.','Serverless altyapının fiziksel sunucusuz olduğu anlamına gelmez. Sağlayıcı kapasiteyi ve çalışma ortamını yönetir; geliştirici kod, izinler, limitler, izleme ve maliyetten sorumludur.','Bir dosya yüklenince çalışan fonksiyon, yalnızca tetiklendiğinde kaynak tüketebilir.','https://docs.aws.amazon.com/lambda/latest/dg/welcome.html','AWS Lambda Docs'),
 conceptCard('vm-container','Altyapı','Sanal makine ve konteyner farkı','VM donanımı sanallaştırır ve ayrı işletim sistemi çalıştırır; konteynerler host çekirdeğini paylaşır.','Sanal makine hypervisor üzerinde kendi işletim sistemi çekirdeğini çalıştırır. Linux konteyneri süreçleri ve dosya görünümünü izole ederken host çekirdeğini paylaşır. İkisi de tek başına güvenlik garantisi değildir.','Bir VM içinde Docker konteynerleri çalıştırmak yaygın bir dağıtım biçimidir.','https://docs.docker.com/get-started/docker-concepts/the-basics/what-is-a-container/','Docker Docs'),
 conceptCard('docker','Altyapı','Docker image ve container','Image dağıtılabilir şablondur; container bu image’dan oluşturulmuş çalışan örnektir.','Docker image katmanlı ve çoğunlukla değişmez bir pakettir. Container, image’dan oluşturulan izole süreç ortamıdır; veri kalıcılığı için volume, yapılandırma için environment/secrets gerekir.','Aynı image’ı yerelde ve CI’da çalıştırıp ortam farklarını azaltmak.','https://docs.docker.com/get-started/docker-concepts/the-basics/what-is-a-container/','Docker Docs'),
 conceptCard('kubernetes-pod','Altyapı','Kubernetes Pod ve Deployment','Pod birlikte planlanan konteynerleri; Deployment ise istenen Pod kopyası durumunu yönetir.','Kubernetes Pod en küçük dağıtılabilir birimidir. Deployment bir ReplicaSet üzerinden Pod kopyalarının istenen sayısını ve sürüm güncellemelerini yönetir. Pod IP’si kalıcı varsayılmamalıdır; erişim için Service kullanılır.','İki replika isteyen Deployment, bir Pod düşerse yenisinin oluşmasını sağlar.','https://kubernetes.io/docs/concepts/workloads/controllers/deployment/','Kubernetes Docs'),
 conceptCard('ci-cd','DevOps','CI ve CD nedir?','Kod değişikliklerini otomatik doğrulama ve kontrollü biçimde teslim etme pratikleri.','Continuous Integration küçük değişiklikleri sık birleştirip otomatik build/test ile sorunları erken yakalamayı hedefler. CD; Continuous Delivery veya Deployment anlamında kullanılır. Deployment otomatik üretime çıkışı da ifade edebilir; ekipte terimi netleştirmek gerekir.','Pull request açılınca testlerin çalışması CI; onaylı sürümü ortama göndermek CD adımıdır.','https://docs.github.com/en/actions/about-github-actions/understanding-github-actions','GitHub Docs'),
 conceptCard('cron','Arka plan işleri','Cron job nedir?','Komut veya işi belirli bir zaman çizelgesinde çalıştıran zamanlayıcı görevi.','Cron geleneksel Unix zamanlayıcısıdır; bulut platformları ve workflow araçları da zamanlanmış işler sunar. Tekrar deneme, eşzamanlı çalışmayı önleme, saat dilimi ve başarısızlık bildirimi tasarlanmalıdır.','Her gece tamamlanmamış raporları üretmek için zamanlanmış görev kullanmak.','https://man7.org/linux/man-pages/man5/crontab.5.html','Linux man-pages'),
 conceptCard('react','Arayüz kütüphanesi','React nedir?','Bileşenler ve state ile kullanıcı arayüzleri kurmak için kullanılan JavaScript kütüphanesi.','React arayüzü bileşenlerden kurar; bileşenler props alabilir ve state tutabilir. Değişen state render çıktısını günceller. React tek başına her uygulama ihtiyacı için tam framework değildir.','Sayaç bileşeni count state’ini artırınca butondaki metin yeniden çizilir.','https://react.dev/learn','React Docs'),
 conceptCard('jsx','React','JSX nedir?','JavaScript içinde HTML’e benzeyen arayüz ağacı ifadeleri yazmayı sağlayan sözdizimi.','JSX JavaScript’in kendisi veya HTML değildir; build araçları bunu JavaScript ifadelerine dönüştürür. JSX içindeki ifade alanları ve bileşen adlandırma kuralları vardır.','<Button label={name} /> ifadesi bir React bileşenini props ile kullanır.','https://react.dev/learn/writing-markup-with-jsx','React Docs'),
 conceptCard('node-npm','JavaScript araçları','Node.js ve npm','Node.js JavaScript çalışma zamanı; npm paket kayıt deposu ve paket yönetim aracıdır.','Node.js JavaScript’i tarayıcı dışında çalıştırır. npm terimi hem paket kayıt deposunu hem de CLI aracını ifade edebilir. package.json proje metadata ve bağımlılık aralıklarını tanımlar; lock dosyası kurulum çözümünü sabitler.','npm ci, lock dosyasındaki bağımlılıkları temiz ve tekrarlanabilir kurar.','https://nodejs.org/en/learn/getting-started/introduction-to-nodejs','Node.js Docs'),
 conceptCard('angular','Arayüz framework’ü','Angular nedir?','TypeScript tabanlı web uygulamaları için bileşen, yönlendirme ve araçlar sunan framework.','Angular; bileşenler, dependency injection, routing ve formlar gibi bütünleşik uygulama yapıtaşları sağlar. React veya Vue ile aynı ürün değil; mimari ve araç kapsamı farklıdır.','https://angular.dev/overview','Angular Docs'),
 conceptCard('rust','Programlama dilleri','Rust ve ownership','Bellek güvenliğini derleme zamanında ownership ve borrowing kurallarıyla sağlamaya çalışan dil.','Rust ownership sistemi birçok bellek hatasını garbage collector olmadan yakalar. Borrow checker, değerlerin yaşam süresi ve eşzamanlı erişim kurallarını doğrular; öğrenme eğrisi ve trade-off’ları vardır.','Aynı değiştirilebilir veriye eşzamanlı iki güvenli referans oluşturmaya izin verilmez.','https://doc.rust-lang.org/book/ch04-00-understanding-ownership.html','The Rust Book'),
 conceptCard('go','Programlama dilleri','Go ne için kullanılır?','Basit derleme ve standart kütüphane ile ağ servisleri ve araçlar kurmaya yönelik programlama dili.','Go statik tipli derlenen dildir; goroutine ve channel gibi araçlarla eşzamanlı programlamayı destekler. Garbage collection kullanır. Tek bir kullanım alanı veya performans garantisi yoktur.','Bir HTTP servisi goroutine’lerle birden fazla isteği eşzamanlı işleyebilir.','https://go.dev/doc/','Go Documentation'),
 conceptCard('github-actions','GitHub','GitHub Actions nedir?','GitHub deposundaki olaylarla workflow ve otomasyon çalıştırma servisi.','Workflow YAML dosyaları event, job, runner ve step tanımlar. Token izinlerini en aza indirmek, üçüncü taraf action sürümlerini sabitlemek ve sırları loglamamak gerekir.','Pull request açılınca testleri çalıştırıp sonucu PR’da göstermek.','https://docs.github.com/en/actions/about-github-actions/understanding-github-actions','GitHub Docs'),
 conceptCard('git-init','Git temeli','git init ve git clone','init yeni yerel depo başlatır; clone mevcut deponun geçmişini yerel kopyaya alır.','git init mevcut dizinde repository metadata’sı oluşturur. git clone uzak depodaki dosya ve geçmişi indirir, varsayılan uzak adı genellikle origin olur.','Yeni proje için init; ekipte var olan projeye katılırken clone.','https://git-scm.com/docs/git'),
 conceptCard('git-status','Git temeli','git status ve çalışma ağacı','Dosyaların değiştirilmiş, staged veya izlenmeyen durumunu gösterir.','git status, HEAD, index (staging area) ve working tree arasındaki farkları özetler. Commit atmadan önce hangi dosyaların dahil olacağını kontrol etmek için temel adımdır.','Yanlışlıkla .env dosyasını stage ettiğini commit öncesinde fark etmek.','https://git-scm.com/docs/git-status'),
 conceptCard('git-add-commit','Git temeli','git add ve git commit','add seçilen değişiklikleri index’e koyar; commit index içeriğinden kayıtlı snapshot üretir.','Git commit tüm çalışma dizinini otomatik kaydetmez; index’e eklenen içeriği kaydeder. Dosyanın yalnızca bazı hunks’larını stage etmek de mümkündür.','git add -p ile bir dosyanın bağımsız iki değişikliğini ayrı commitlere ayırmak.','https://git-scm.com/docs/git-add'),
 conceptCard('git-log-diff','Git inceleme','git log ve git diff','log commit geçmişini; diff iki durum arasındaki içerik farkını gösterir.','git log commit metadata ve geçmişi listeler. git diff çalışma ağacı, index veya commitler arasındaki değişiklikleri karşılaştırır. Doğru karşılaştırma hedefini seçmek, neyin kaydedileceğini anlamaya yardım eder.','Commit atmadan önce git diff --staged ile stage edilen farkı gözden geçirmek.','https://git-scm.com/docs/git-diff'),
 conceptCard('git-branch-switch','Git dalları','Branch ve switch','Branch commit geçmişinde hareketli bir işaretçi; switch başka branch’e geçiş komutudur.','Branch ana commit grafiğinden ayrılan hafif bir referanstır. git switch branch’ler arasında geçiş yapar; git switch -c yeni branch oluşturup ona geçebilir.','Yeni özelliği main üzerinde değil, ayrı feature branch’inde geliştirmek.','https://git-scm.com/docs/git-branch'),
 conceptCard('git-merge','Git dalları','git merge ve merge commit','Bir branch’in geçmişini mevcut branch’e birleştirir; gerekirse iki ebeveynli merge commit üretir.','Merge, iki tarihçenin ortak atası üzerinden değişiklikleri birleştirir. Fast-forward mümkünde branch işaretçisi ileri alınabilir; aksi durumda merge commit oluşabilir. Conflict çözümü sonrası test edilir.','Feature branch’i main’e merge edip iki taraftaki commit geçmişini korumak.','https://git-scm.com/docs/git-merge'),
 conceptCard('git-rebase','Git dalları','git rebase ne yapar?','Commitleri yeni bir taban üzerine yeniden uygulayarak tarihçeyi yeniden yazar.','Rebase, branch commitlerini yeni tabanın üstünde yeniden oluşturarak lineer tarihçe sağlayabilir. Commit kimlikleri değişir; paylaşılmış commitlerde ekip koordinasyonu olmadan rebase etmek başkalarının geçmişini zorlaştırabilir.','Paylaşılmamış feature branch’ini main’in sonuna rebase edip sonra test etmek.','https://git-scm.com/docs/git-rebase'),
 conceptCard('git-remote-fetch','Git uzak depoları','remote, fetch ve pull','remote depo adresidir; fetch uzak referansları indirir; pull fetch sonrası entegrasyon uygular.','git fetch uzak branch bilgilerini indirir ama mevcut branch’e otomatik birleştirmez. git pull varsayılan olarak fetch ve ardından merge veya yapılandırılmış rebase yapar. Önce fetch ile farkı inceleyebilirsin.','Uzak main’i fetch et, log/diff ile değişiklikleri gör, sonra uygun biçimde birleştir.','https://git-scm.com/docs/git-fetch'),
 conceptCard('git-push','Git uzak depoları','git push ve non-fast-forward','Push yerel commitleri uzak referansa gönderir; non-fast-forward uzak geçmişin geride kalacağını bildirir.','Push, uzak branch’i güvenli biçimde ileri taşıyamıyorsa reddedilebilir. Önce fetch edip uzak commitleri anla, sonra merge/rebase yap, test et ve yeniden pushla. Force push ekip geçmişini değiştirebilir.','Non-fast-forward görünce önce git status ve git fetch; hemen --force kullanma.','https://git-scm.com/docs/git-push'),
 conceptCard('git-conflict','Git hata ayıklama','Merge conflict nasıl çözülür?','Git’in otomatik birleştiremediği aynı bölgedeki değişiklikleri bilinçli biçimde uzlaştırma.','Conflict işaretleri iki tarafın metnini gösterir; dosyayı açıp istenen son durumu elle kur, işaretleri kaldır, test et, sonra git add ile çözümü bildir. “ours” veya “theirs” seçimi her zaman doğru değildir.','İki PR aynı doğrulama fonksiyonunu değiştirdiyse, amaçlanan davranışı ve her iki testi anlamak.','https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/addressing-merge-conflicts/about-merge-conflicts','GitHub Docs'),
 conceptCard('git-revert-reset','Git geri alma','git revert ve git reset farkı','revert yeni ters commit oluşturur; reset mevcut branch işaretçisini başka commit’e taşır.','git revert paylaşılan tarihçeyi silmeden değişikliği tersine çevirir. git reset branch referansını ve seçeneğe göre index/working tree durumunu değiştirir. Reset’in etkisi seçeneklere bağlıdır; commitlenmemiş veri kaybı riski vardır.','Üretim branch’indeki hatalı commit’i revert etmek, ortak tarihi korur.','https://git-scm.com/docs/git-revert'),
 conceptCard('git-stash','Git geçici değişiklikler','git stash ne zaman kullanılır?','Commit etmeye hazır olmayan çalışma ağacı değişikliklerini geçici rafa kaldırır.','git stash seçili değişiklikleri saklayıp çalışma ağacını temizleyebilir. Stash yerel bir geçici kolaylıktır; kalıcı yedek veya ekip paylaşım mekanizması değildir. Daha uzun yaşayan iş için branch ve commit daha görünürdür.','Acil bugfix branch’ine geçmeden önce WIP değişikliklerini stash etmek.','https://git-scm.com/docs/git-stash'),
 conceptCard('git-cherry-pick','Git seçili commit','git cherry-pick nedir?','Başka branch’teki belirli commit değişikliğini mevcut branch’e yeni commit olarak uygular.','Cherry-pick commitin değişikliğini seçili branch’te yeniden uygular; yeni commit kimliği oluşur. Aynı değişikliği iki branch’te çoğaltmak ileride merge karmaşası yaratabilir; sınırlı ve bilinçli kullanılır.','Acil bir düzeltmeyi release branch’ine tek commit olarak almak.','https://git-scm.com/docs/git-cherry-pick'),
 conceptCard('git-tag','Git sürümleme','Git tag nedir?','Belirli bir commit’e sürüm adı veren referans; release işaretlemek için kullanılır.','Tag commitleri yeniden adlandırmaz; belirli commit’i adlandırır. Annotated tag açıklama ve imza metadata’sı taşır; lightweight tag basit işaretçidir.','v1.4.0 annotated tag’i test edilmiş release commit’ini gösterebilir.','https://git-scm.com/book/en/v2/Git-Basics-Tagging'),
 conceptCard('gitignore','Git dosyaları','.gitignore ne yapar?','Git’in izlemeye alınmamış eşleşen dosyaları görmezden gelmesini söyler.','.gitignore zaten izlenen dosyayı depodan çıkarmaz; yalnızca izlenmeyen yolların eklenmesini engeller. İzlenen dosyayı kaldırmak için git rm --cached gerekir. Gizli anahtarları commit etmemek için ignore tek başına yeterli güvenlik tedbiri değildir.','node_modules/ klasörünü yeni clone’larda Git’e eklememek.','https://git-scm.com/docs/gitignore'),
 conceptCard('github-pr','GitHub ekip akışı','Pull request nedir?','Branch değişikliklerini inceleme, tartışma ve kontrollerle hedef branch’e alma isteği.','Pull request GitHub üzerinde branch farkını görünür kılar; yorumlar, review ve CI kontrolleri ile ekipçe değerlendirilebilir. PR tek başına Git’in parçası değildir; GitHub iş akışı özelliğidir.','Bir PR’da testlerin yeşil olması ve değişikliklerin gözden geçirilmesi.','https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/proposing-changes-to-your-work-with-pull-requests/about-pull-requests','GitHub Docs'),
 conceptCard('git-actions','GitHub otomasyon','GitHub Actions workflow','Depo olaylarına bağlı otomasyon tanımlar; job’lar runner üzerinde step’lerle çalışır.','Workflow .github/workflows altında YAML dosyasıdır. Trigger, job, runner ve step tanımlanır. En az token izni, üçüncü taraf action sürümü sabitleme ve hassas değerleri secret olarak verme güvenlik için önemlidir.','Pull request’te npm test çalıştırıp başarısızsa merge’i engellemek.','https://docs.github.com/en/actions/about-github-actions/understanding-github-actions','GitHub Docs'),
 conceptCard('aws-basics','Bulut','AWS temel servisleri','AWS, hesap, bölge ve izin modeli üzerinden çok sayıda bulut hizmeti sunar.','Örnek temel servisler: EC2 sanal makine, S3 nesne depolama, RDS yönetilen ilişkisel veritabanı, Lambda olay güdümlü fonksiyon, IAM kimlik ve izin yönetimi. Her servis için bölge, erişim politikası, maliyet ve veri yaşam döngüsü düşünülür.','Bir web uygulaması EC2’de çalışırken statik görselleri S3’te tutabilir; IAM yalnız gereken erişimi verir.','https://docs.aws.amazon.com/whitepapers/latest/aws-overview/introduction.html','AWS Overview'),
 conceptCard('azure-gcp','Bulut','Azure ve Google Cloud','Farklı sağlayıcıların işlem, depolama, ağ, veri ve yönetilen uygulama servisleri.','Azure ve Google Cloud AWS gibi çok sayıda servisi olan bulut platformlarıdır. Ürün adları birebir eşdeğer değildir; seçim yetenek, ekip deneyimi, uyumluluk, mevcut altyapı ve toplam maliyete göre yapılır.','Container uygulaması Azure Container Apps veya Google Cloud Run gibi yönetilen servislerde çalıştırılabilir.','https://cloud.google.com/docs/overview','Google Cloud Docs'),
 conceptCard('nginx','Web sunucusu','Nginx ve reverse proxy','HTTP sunucusu, reverse proxy, cache ve yük dağıtma görevlerinde kullanılan yazılım.','Nginx istemci isteklerini statik dosyalara veya arka uç servislerine yönlendirebilir. Reverse proxy yapılandırmasında header aktarımı, TLS, timeout, buffering ve gerçek istemci adresi gibi ayrıntılar önemlidir.','/api yolunu uygulama sunucusuna, statik dosyaları doğrudan web sunucusuna iletmek.','https://nginx.org/en/docs/','Nginx Docs'),
 conceptCard('apache-httpd','Web sunucusu','Apache HTTP Server','Modüler HTTP sunucusu; sanal host, proxy ve erişim kuralları yapılandırabilir.','Apache HTTP Server istemcilerden HTTP istekleri alıp içerik veya proxy yanıtı sunar. Nginx ile “hangisi her zaman daha hızlı” diye genellenemez; kullanım ve yapılandırma belirleyicidir.','Sanal host ile aynı makinede birden çok alan adına farklı içerik sunmak.','https://httpd.apache.org/docs/2.4/','Apache HTTP Server Docs'),
 conceptCard('vpn','Ağ güvenliği','VPN ne sağlar?','Cihaz ile VPN ağı arasında şifreli bir tünel kuran ağ teknolojisi.','VPN trafiği koruyabilir ve özel ağa erişim sağlayabilir; web’de anonimlik veya uçtan uca güvenlik garantisi vermez. VPN sağlayıcısı ve tünelin çıkış noktası da güven sınırının parçasıdır.','Şirket ağına uzaktan erişimde cihaz önce kurumsal VPN’e bağlanır.','https://www.cloudflare.com/learning/access-management/what-is-a-vpn/','Cloudflare Learning Center'),
 conceptCard('web-scraping','Veri toplama','Web scraping ve otomasyon','Web sayfalarından programla bilgi toplama; erişim şartları ve kaynak yükü gözetilmelidir.','Scraping HTML veya API yanıtlarından veri çıkarabilir. Önce resmi API olup olmadığı araştırılır; robots.txt, kullanım şartları, telif, kişisel veri, hız sınırı ve sitenin hizmetine etkisi değerlendirilir. Selenium tarayıcı otomasyonudur; her scraping işi için en iyi araç değildir.','Yayınlanmış bir ürün kataloğunu izinli ve makul hızla işlemek.','https://www.selenium.dev/documentation/','Selenium Docs'),
 conceptCard('jamstack','Web mimarisi','Jamstack yaklaşımı','Statik ön üretim, API ve istemci koduyla web içeriğini ayrıştıran mimari yaklaşım.','Jamstack tek bir framework değildir. Sayfalar build sırasında üretilebilir; istemci API’lere bağlanır. İçerik güncelliği, build süresi, kişiselleştirme ve erişim kontrolü mimaride ayrıca ele alınmalıdır.','Dokümantasyon sayfalarını statik üretip arama veya üyelik verisini API ile sunmak.','https://jamstack.org/','Jamstack.org'),
 conceptCard('sudo','Linux','sudo ve en az ayrıcalık','Bir kullanıcının belirli komutları tanımlı yönetici yetkisiyle çalıştırmasını sağlar.','sudo, root olarak sürekli çalışmak yerine yapılandırılmış yetki yükseltmesi sağlar. Komutun etkisini incelemek gerekir; `sudo` kullanmak komutu güvenli yapmaz. Üretim sistemlerinde kapsamlı izin vermekten kaçınılır.','Paket yüklemek için tek bir yönetim komutunu çalıştırmak; tüm uygulamayı root başlatmamak.','https://www.sudo.ws/docs/man/1.8.27/sudo.man/','sudo Documentation'),
 conceptCard('mysql','Veritabanı','MySQL nedir?','SQL kullanan ilişkisel veritabanı yönetim sistemi.','MySQL tablolar, indeksler, transaction’lar ve SQL sorguları sunar. MySQL ve PostgreSQL arasında tek bir evrensel “daha iyi” yoktur; özellikler, çalışma ortamı, ekip ve uyumluluk karşılaştırılır.','Kullanıcı ve sipariş tablolarını foreign key ile ilişkilendirmek.','https://dev.mysql.com/doc/','MySQL Reference Manual'),
 conceptCard('tensorflow','Makine öğrenmesi','TensorFlow nedir?','Makine öğrenmesi modelleri geliştirme ve çalıştırmaya yönelik açık kaynak ekosistemi.','TensorFlow tensor hesapları ve otomatik türev gibi yapıtaşları sağlar. Model eğitim/veri pipeline’ı, model değerlendirmesi, dağıtım hedefi ve sürüm uyumluluğu ayrıca tasarlanır. Kullanmak doğru model veya veri kalitesi garantisi değildir.','Eğitim verisinden bir sınıflandırıcı eğitip ayrı doğrulama kümesinde ölçmek.','https://www.tensorflow.org/learn','TensorFlow Docs'),
 conceptCard('solidity','Programlama dilleri','Solidity nedir?','Ethereum Virtual Machine için akıllı sözleşmeler yazmaya yönelik statik tipli dil.','Solidity sözleşmeleri zincir üzerinde kalıcı ve çoğu zaman değiştirilemez davranışlar oluşturabilir. Güvenlik, erişim kontrolü, işlem maliyeti ve test kritik önemdedir; sözleşme kodu üretime çıkmadan denetlenmelidir.','Rol kontrolü olmayan para çekme fonksiyonu fonların başkası tarafından alınmasına yol açabilir.','https://docs.soliditylang.org/en/latest/','Solidity Docs'),
 conceptCard('laravel','Web framework','Laravel nedir?','PHP ile web uygulamaları kurmak için routing, ORM, migration ve diğer araçları sunan framework.','Laravel uygulama geliştirmede ortak web görevleri için bütünleşik yapıtaşları sağlar. Sürüm ve eklenti uyumluluğu uygulama gereksinimine göre doğrulanır.','Route isteği controller’a iletir; Eloquent model veritabanı kaydını temsil edebilir.','https://laravel.com/docs','Laravel Docs'),
 conceptCard('django','Web framework','Django nedir?','Python ile web uygulamaları kurmak için ORM, admin, routing ve güvenlik yapıtaşları sunan framework.','Django birçok yaygın web işini bütünleşik sunar; framework varsayılanları güvenli yapılandırma ihtiyacını ortadan kaldırmaz. Deployment checklist ve production settings ayrıca uygulanır.','Model değişikliğini migration üretip veritabanına uygulamak.','https://docs.djangoproject.com/en/stable/','Django Docs'),
 conceptCard('ajax-fetch','Web API','AJAX, Fetch ve XHR','Sayfanın tamamını yenilemeden tarayıcıdan HTTP isteği gönderme yaklaşımı.','AJAX tarihsel olarak asenkron HTTP isteklerini anlatır; XML şart değildir. Güncel tarayıcılarda Fetch yaygındır, XMLHttpRequest hâlâ kullanılır. Promise hatalarını, HTTP durum kodlarını ve CORS’u ayrı ele almak gerekir.','Arama alanına yazıldığında fetch ile sonuç isteyip sonuç listesini güncellemek.','https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch','MDN Web Docs'),
 conceptCard('selenium','Test ve otomasyon','Selenium ne işe yarar?','Web tarayıcılarını WebDriver protokolüyle otomatik kontrol eden araçlar.','Selenium tarayıcı etkileşimlerini otomatikleştirir; uçtan uca test, uyumluluk ve bazı otomasyon işlerinde kullanılır. Sabit bekleme yerine koşullu beklemeler, kararlı seçiciler ve temiz test verisi tercih edilir.','Login akışında form doldurup doğrulama mesajını beklemek.','https://www.selenium.dev/documentation/webdriver/','Selenium Docs'),
 conceptCard('jquery','JavaScript kütüphanesi','jQuery nedir?','DOM işlemleri ve olay yönetimi için API sunan JavaScript kütüphanesi.','jQuery eski tarayıcı farklılıklarını soyutlamaya yardımcı oldu ve mevcut projelerde sık görülür. Modern tarayıcıların yerel DOM ve Fetch API’leri birçok kullanım ihtiyacını karşılayabilir; mevcut kod tabanında bağımlılık ve bakım maliyeti değerlendirilir.','Mevcut bir jQuery uygulamasında selector ile form alanlarını bulmak.','https://api.jquery.com/','jQuery API Docs')
];
const quiz=[
 {area:'C# · çalışma zamanı',question:'C# kodunu bilgisayarın çalıştırdığı makine koduna dönüştürme ve çalışma zamanı hizmetlerini sağlama sürecinde CLR’nin rolü hangisidir?',context:'Bir C# projesini derleyip çalıştırdığında kaynak kod ile çalışan program arasında neler olduğunu düşün.',options:['CLR yalnızca kodu yazdığın editördür.','CLR, .NET managed kodunu çalıştıran runtime’dır; yükleme, yürütme ve runtime hizmetlerinde rol alır.','CLR, C# projesindeki tüm SQL tablolarını oluşturur.'],answer:1,explain:'Doğru. C# derleyicisi IL ve metadata içeren çıktılar üretir; CLR bu managed kodu yükleyip çalıştırır ve garbage collection gibi runtime hizmetleri sağlar. Detaylar için Microsoft Learn kaynağına bakabilirsin.',source:sources.clr},
 {area:'React · kod okuma',question:'Bu bileşen ekranda ilk çizildiğinde hangi mesaj görünür?',context:'State güncellemesinin render üzerindeki etkisini tahmin et.',code:'function Counter() {\n  const [count, setCount] = useState(0);\n  return <button onClick={() => setCount(count + 1)}>\n    {count === 0 ? "Başla" : `Sayı: ${count}`}\n  </button>;\n}',options:['Başla','Sayı: 0','Ekran boş kalır; state başlangıcı sayılmaz.'],answer:0,explain:'İlk render’da count değeri 0’dır, bu yüzden koşul “Başla” metnini seçer. Tıklama setCount ile state’i günceller ve React yeni değere göre tekrar render eder.',source:{label:'React Docs',url:'https://react.dev/learn/state-a-components-memory'}},
 {area:'Git · hata teşhisi',question:'Push sırasında “non-fast-forward” uyarısı aldın. İlk güvenli adım ne olmalı?',context:'Uzak branch’te sende olmayan commitler olabilir. Geçmişi anlamadan zorla göndermek ekip arkadaşının commitlerini kaybettirebilir.',options:['Durumu ve uzak değişiklikleri inceleyip branch’i güvenli biçimde güncellemek.','Her durumda git push --force çalıştırmak.','Yerel branch’i silip aynı dosyaları tekrar yazmak.'],answer:0,explain:'Önce git status ve git fetch ile durumu incele; ortak geçmişteki uzak commitleri gör. Sonra ekip akışına göre merge veya rebase et ve test ederek pushla. Force push paylaşılan geçmişi değiştirebilir.',source:sources.git},
 {area:'API · kavram',question:'Bir tarayıcı isteği CORS hatası veriyor. Bu mesaj en doğru şekilde ne anlatır?',context:'Tarayıcı konsolundaki hata, çoğu zaman API’nin sunucu tarafında hiç çalışmadığı anlamına gelmez.',options:['Tarayıcı, sunucudan gelen CORS izin başlıkları nedeniyle yanıtı web sayfasının JavaScript koduna açmıyor olabilir.','Şifre kesinlikle yanlış demektir.','Veritabanı kesinlikle kapalı demektir.'],answer:0,explain:'CORS, tarayıcının farklı origin isteklerine uyguladığı erişim politikasıdır. Sunucu uygun Access-Control-Allow-Origin yanıtını vermelidir. Bu, API’nin ağda hiç yanıt vermediği anlamına gelmeyebilir.',source:{label:'MDN Web Docs',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS'}}
];
let state={view:'today',quizIndex:0,quizMode:false,selected:null,answered:false,completed:0,answerText:'',errorSolved:false,conceptOpen:null,newsSummaries:{},errorHint:0};
const root=document.getElementById('viewRoot');
const stored=JSON.parse(localStorage.getItem('realdev-progress')||'{}');Object.assign(state,{completed:stored.completed||0,errorSolved:stored.errorSolved||false,answerText:stored.answerText||''});
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(){localStorage.setItem('realdev-progress',JSON.stringify({completed:state.completed,errorSolved:state.errorSolved,answerText:state.answerText}))}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400)}
function link(source,label='Kaynağı aç'){return `<a href="${source.url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}
function heading(eyebrow,title,desc,right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`}
function today(){const progress=Math.min(100,Math.round(state.completed/4*100));return `<div class="welcome-row"><div><h1>Merhaba, geliştirici</h1><p>Bugün küçük bir adım atalım. Önce düşün, sonra dene, en son açıkla.</p></div><div class="streak">✦ <strong>${state.completed}</strong> çalışma tamamlandı</div></div>
<section class="hero-card"><div class="hero-content"><div class="hero-overline"><span class="live-dot"></span> BUGÜNÜN ÇALIŞMASI · 15 DK</div><h2>Kodu yalnızca çalıştırma. Ne yaptığını da bil.</h2><p>React’te state güncellemesini tahmin et, ardından C# runtime’ının rolünü kendi cümlelerinle anlat.</p><div class="hero-meta"><span>◉ Kod okuma</span><span>↗ Kavram açıklama</span><span>◷ 4 kısa adım</span></div></div><button class="primary-button" data-action="start-quiz">Çalışmaya başla <span>→</span></button></section>
<div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Bugünkü rota</h2><button class="subtle-link" data-view="map">Tüm beceriler →</button></div><div class="task-list"><div class="task-row" data-action="start-quiz"><span class="task-icon purple">⌘</span><span class="task-copy"><strong>Kod davranışını tahmin et</strong><small>React · state ve yeniden render</small></span><span class="task-time">4 dk</span><span class="task-arrow">›</span></div><div class="task-row" data-view="errors"><span class="task-icon orange">⌁</span><span class="task-copy"><strong>Bir Git hatasını çöz</strong><small>non-fast-forward · güvenli inceleme</small></span><span class="task-time">5 dk</span><span class="task-arrow">›</span></div><div class="task-row" data-view="concepts"><span class="task-icon blue">▤</span><span class="task-copy"><strong>Bir kavramı kendi cümlenle açıkla</strong><small>C# · Common Language Runtime</small></span><span class="task-time">3 dk</span><span class="task-arrow">›</span></div></div><div class="panel-foot"><span>İlerleme bu cihazda kaydedilir</span><span>${progress}% rota</span></div></section>
<section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Beceri haritandan</h2><span class="eyebrow">KEŞİF AŞAMASI</span></div><div class="skill-list"><div class="skill-row"><span class="skill-name">React · kod okuma</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill" style="width:0"></div></div></div><div class="skill-row"><span class="skill-name">C# · .NET temelleri</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill warm" style="width:0"></div></div></div><div class="skill-row"><span class="skill-name">Git · hata çözme</span><span class="skill-state">${state.errorSolved?'bir görev tamamlandı':'ölçülmedi'}</span><div class="skill-track"><div class="skill-fill" style="width:${state.errorSolved?25:0}%"></div></div></div><div class="skill-row"><span class="skill-name">Unity · C#</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill warm" style="width:0"></div></div></div></div><div class="panel-foot"><span>İlk kısa tarama ile başlangıç seviyesi oluşur.</span></div></section></div>
<div class="tip-card"><span class="tip-spark">✳</span><div><strong>Çalışma ipucu</strong><p>AI’ın ürettiği bir kodu kullanmadan önce kendine sor: Girdi ne? Çıktı ne? Hata olursa ilk hangi kanıta bakarım?</p></div></div>
<div class="section-label">Güncel gelişmeler</div><div class="news-inline">${news.slice(0,2).map((n,i)=>`<article class="news-mini"><div class="source-line"><span>${n.date} · ${n.tag}</span><span class="source-badge">${n.kind}</span></div><h3>${n.title}</h3><p>${n.body}</p><button class="text-button" data-view="news">Haberleri gör →</button></article>`).join('')}</div>`}
function quizView(){if(!state.quizMode)return `${heading('BECERİ TARAMASI','Neleri gerçekten anladığını keşfet','Kısa görevler kod okuma, hata teşhisi ve teknik anlatım pratiği sunar. “Bilmiyorum” demek de geçerli bir başlangıçtır.',`<span class="day-pill">10–15 dakika</span>`)}<section class="quiz-card"><p class="quiz-context">Önce kendin dene, sonra açıklamayı ve kaynağı incele.</p><button class="primary-button" data-action="start-quiz">Tarama görevlerine başla <span>→</span></button></section>`;return quizCard()}function quizCard(){const q=quiz[state.quizIndex];if(!q)return `<section class="quiz-card"><div class="eyebrow">TARAMA TAMAMLANDI</div><h2 class="quiz-question" style="margin-top:10px">İlk keşif turu bitti.</h2><p class="quiz-context">${state.completed} kısa görev tamamladın. Bu ilk tur yalnızca başlangıç sinyali; daha doğru beceri haritası için düzenli pratikte farklı örnekler de çözeceğiz.</p><button class="primary-button" data-action="reset-quiz">Bir tur daha yap <span>→</span></button> <button class="secondary-button" data-view="today">Bugüne dön</button></section>`;return `<section class="quiz-card"><div class="quiz-top"><span class="eyebrow">BAŞLANGIÇ TARAMASI · ${q.area}</span><span class="quiz-step">${state.quizIndex+1} / ${quiz.length}</span></div><div class="progress"><span style="width:${(state.quizIndex+1)/quiz.length*100}%"></span></div><h2 class="quiz-question">${q.question}</h2><p class="quiz-context">${q.context}</p>${q.code?`<div class="code-block">${esc(q.code)}</div>`:''}<div class="choice-list" style="margin-top:${q.code?'15px':'0'}">${q.options.map((o,i)=>`<button class="choice ${state.selected===i?'selected':''}" data-choice="${i}" ${state.answered?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div>${state.answered?`<div class="result-box ${state.selected===q.answer?'':'warning'}"><h4>${state.selected===q.answer?'İyi yakaladın.':'Burada tekrar düşünmeye değer.'}</h4>${q.explain}<div style="margin-top:8px;font-size:10px">${link(q.source,'Bilgiyi doğrula')}</div></div>`:''}<div class="quiz-actions"><span class="text-muted">${state.answered?'Cevabın ve açıklama kaydedildi.':'Emin değilsen “Şimdilik bilmiyorum” diyebilirsin.'}</span>${state.answered?`<button class="primary-button" data-action="next-quiz">${state.quizIndex===quiz.length-1?'Tamamla':'Sonraki'} <span>→</span></button>`:`<button class="secondary-button" data-action="dont-know">Şimdilik bilmiyorum</button>`}</div></section>`}
function mapView(){return `${heading('GELİŞİMİN','Beceri haritam','Bu ilk prototipte görev cevapları cihazında saklanır. Alanlar görevlerle zaman içinde keşfedilir; henüz değerlendirilmemiş beceriye seviye atamayız.')}<div class="two-col"><section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Çalışma alanları</h2><span class="eyebrow">HEDEF: GENEL EKSİKLERİ KAPAT</span></div><div class="skill-list">${[['Frontend','JavaScript · TypeScript · React'],['Backend','Java · Python · C# / .NET'],['Veritabanı','SQL · veri modeli · DDL'],['Git ve ekip çalışması','branch · merge · pull request'],['Test ve kalite','unit · integration · debug'],['DevOps ve cloud','CI/CD · AWS temelleri'],['Unity ve mobil oyun','C# · oyun döngüsü · build'],['AI ile üretim','kod açıklama · doğrulama']].map(x=>`<div class="task-row"><span class="task-icon purple">◇</span><span class="task-copy"><strong>${x[0]}</strong><small>${x[1]}</small></span><span class="chip">Henüz ölçülmedi</span></div>`).join('')}</div></section><aside class="panel panel-pad"><h2 class="panel-title">Ölçüm nasıl işler?</h2><p class="quiz-context" style="margin-top:12px">Bir doğru cevap tek başına “uzman” anlamına gelmez. Kod yazma, açıklama, hata ayıklama ve yeni senaryoya aktarım farklı görevlerle gözlemlenir.</p><div class="error-steps"><div class="error-step"><span class="number">1</span><div><strong>Önce bağımsız dene</strong><p>İpucu almadan ne yapabildiğin görünür.</p></div></div><div class="error-step"><span class="number">2</span><div><strong>Gerekince ipucu al</strong><p>Hangi yardımın gerektiği de ilerlemeni açıklar.</p></div></div><div class="error-step"><span class="number">3</span><div><strong>Başka örnekte tekrar et</strong><p>Bilgiyi yeni duruma uygulamanı kontrol ederiz.</p></div></div></div><button class="primary-button" style="margin-top:16px" data-action="start-quiz">Kısa taramayı başlat <span>→</span></button></aside></div>`}
function errorsView(){return `${heading('HATA LABORATUVARI','Hata mesajını okuyup çözüm yolunu bul','Gerçekçi çıktıları incele: mesaj ne söylüyor, neyi henüz bilmiyorsun ve hangi kanıtı toplarsın?')}<div class="two-col"><section class="feature-card"><div class="eyebrow">GIT · PUSH HATASI · BAŞLANGIÇ</div><h2 class="quiz-question" style="margin-top:10px">Uzak branch ileride görünüyor</h2><div class="error-meta"><span class="chip red">non-fast-forward</span><span class="chip">Git</span><span class="chip">Güvenli teşhis</span></div><div class="code-block">! [rejected] main -&gt; main (non-fast-forward)\nerror: failed to push some refs\nhint: Updates were rejected because the tip of your current branch is behind its remote counterpart.</div><p class="quiz-context" style="margin-top:15px">Şu an <code>main</code> branch’indesin. Ekip arkadaşın uzak branch’e commit gönderdi; sende henüz fetch edilmemiş. İlk ne yaparsın?</p><textarea id="errorAnswer" class="answer-area" placeholder="Önce şunu kontrol ederim… çünkü…">${esc(state.answerText)}</textarea><div class="answer-tools"><button class="mic-button" data-action="mic">🎙 Sesli açıkla</button><button class="primary-button" data-action="check-error">Yanıtımı kaydet <span>→</span></button><button class="subtle-link" data-action="hint">İpucu ${state.errorHint?'gösterildi':''}</button></div>${state.errorHint?`<div class="result-box" style="margin-top:13px"><h4>İpucu</h4>Önce yerel çalışma ağacını ve branch’in uzakla ilişkisini incele. <code>git fetch</code> uzak bilgileri indirir ama dosyalarını birleştirmez. Ardından commit farkını görüp ekip akışına uygun merge veya rebase planla.</div>`:''}${state.errorSolved?`<div class="result-box"><h4>Yanıtın bu cihazda saklandı; otomatik doğruluk puanı yok.</h4>${/--force|push\s+-f/i.test(state.answerText)?'Force push paylaşılan geçmişi değiştirebilir; ekip akışını ve remote geçmişini incelemeden kullanma.':'Güvenli bir teşhis yolu; önce git status/git fetch ile uzak farkı incele, sonra ekip akışına uygun merge veya rebase seç, test et ve pushla.'} ${link(sources.git,'Git merge dokümanı')}</div>`:''}</section><aside class="panel panel-pad"><h2 class="panel-title">Hata ayıklama sırası</h2><p class="quiz-context" style="margin:8px 0 17px">Mesajı gördüğünde kendine şu soruları sor:</p><div class="error-steps"><div class="error-step"><span class="number">1</span><div><strong>Ne başarısız oldu?</strong><p>Komut ve hata türünü mesajdan ayır.</p></div></div><div class="error-step"><span class="number">2</span><div><strong>Hangi bilgi eksik?</strong><p>Branch durumu, son commit ve remote farkı.</p></div></div><div class="error-step"><span class="number">3</span><div><strong>En risksiz kanıtı topla</strong><p>git status, git branch -vv, git fetch.</p></div></div><div class="error-step"><span class="number">4</span><div><strong>Sonucu doğrula</strong><p>Çözümden sonra test edip push durumuna bak.</p></div></div></div><div class="source-note" style="margin-top:17px"><strong>Kaynak standardı:</strong> Öğretici adımlar resmi araç dokümantasyonuyla karşılaştırılır. Topluluk cevapları örnek olabilir; tek başına doğruluk kanıtı sayılmaz.</div></aside></div><div class="section-label">Sonraki hata konuları</div><div class="github-grid">${[['IDE ve SDK','dotnet SDK bulunamadı','PATH ve yüklenen SDK sürümlerini incele.'],['API ve tarayıcı','CORS hatası','Tarayıcı policy’sini ve response başlıklarını ayır.'],['Unity build','Android build başarısız','İlk gerçek error satırını ve build ortamını bul.']].map((x,i)=>`<article class="practice-tile" data-action="coming-error"><span>YAKINDA · ${['.NET','HTTP','UNITY'][i]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`}
function conceptsView(){const cards=[...concepts,...expandedConcepts],c=cards.find(x=>x.id===state.conceptOpen);return `${heading('KAVRAM ATÖLYESİ','Adını duydun. Şimdi gerçekten anla.',`${cards.length} kaynaklı kavram · Git’te günlük branch akışından conflict ve geçmişi geri almaya kadar. Önce kısa anlatım, sonra kendi cümlenle açıkla.`)}<label class="concept-search-label" for="conceptSearch">Kavram veya Git komutu ara</label><input id="conceptSearch" class="concept-search" type="search" placeholder="Örn. API, cache, git rebase…" autocomplete="off"><p id="conceptSearchCount" class="concept-search-count" aria-live="polite">${cards.length} kavram</p><div class="concept-grid">${cards.map(x=>`<article class="concept-card" data-concept="${x.id}"><span class="concept-type">${x.type}</span><h3>${x.name}</h3><p>${x.desc}</p><div class="concept-footer"><span>Kaynaklı anlatım</span><span>Öğren →</span></div></article>`).join('')}</div>${c?`<article class="concept-detail"><div class="eyebrow">${c.type}</div><h2>${c.name}</h2><p>${c.body}</p><div class="analogy"><strong>Bir örnekle düşün:</strong> ${c.analogy}</div><div class="source-note" style="margin-top:13px"><strong>Kontrol edilebilir kaynak:</strong> ${link(c.source,c.source.label)}</div><label for="conceptAnswer" class="field-label">Şimdi kendi cümlenle açıkla</label><textarea id="conceptAnswer" class="answer-area" placeholder="Bunu başka bir geliştiriciye şöyle anlatırdım…"></textarea><div class="answer-tools"><button class="mic-button" data-action="mic" data-target="conceptAnswer">🎙 Sesli anlat</button><button class="primary-button" data-action="check-concept">Açıklamamı gözden geçir <span>→</span></button><span class="text-muted">Bu prototipte otomatik yapay zekâ değerlendirmesi yok.</span></div><div id="conceptFeedback"></div></article>`:''}<div class="source-note" style="margin-top:15px"><strong>Bilgi disiplini:</strong> Tanımlar MDN, Git, GitHub, Kubernetes, PostgreSQL ve üretici belgeleri gibi kaynaklara bağlanır. Topluluk yazıları resmi davranış tanımının yerine geçmez.</div>`}
function newsView(){return `${heading('YAZILIM HABERLERİ','Gündemi takip et, etkisini anla','AI modelleri, geliştirici araçları ve altyapı gelişmeleri. Kaynağa git veya kısa özeti aç.',`<span class="day-pill">Kontrol: 5 Ekim 2026</span>`)}<div class="source-note"><strong>Güvenilirlik kuralı:</strong> Bu akıştaki kartlar ilk sürüm için elle seçilmiş kaynaklı örneklerdir, canlı haber akışı değildir. Yayın tarihi kaynak sayfasından alınmıştır. Her kartta asıl kaynağa gidebilirsin.</div><div class="news-list">${news.map((n,i)=>`<article class="news-card"><div class="news-card-top"><span class="source-badge">${n.kind}</span><span>${n.date}</span><span>·</span><span>${n.tag}</span></div><h3>${n.title}</h3><p>${n.body}</p><div class="news-summary ${state.newsSummaries[i]?'open':''}" id="summary-${i}"><strong>Kısa özet:</strong> ${n.summary}</div><div class="news-actions"><button data-action="summary" data-index="${i}">${state.newsSummaries[i]?'Özeti kapat':'Haberi özetle'}</button>${link(n.source,`Asıl kaynak: ${n.source.label}`)}</div></article>`).join('')}</div><div class="section-label">Kaynak yaklaşımı</div><div class="two-col"><section class="panel panel-pad"><h2 class="panel-title">Resmi kaynaklar</h2><p class="quiz-context" style="margin:8px 0 0">Sürüm, API davranışı ve yeni model özellikleri için önce ürün dokümantasyonu, changelog veya resmi proje blogu. Üçüncü taraf açıklamalar, kaynağa göreli yorumlarıyla sunulur.</p></section><section class="panel panel-pad"><h2 class="panel-title">Topluluk kaynakları</h2><p class="quiz-context" style="margin:8px 0 0">Medium ve Stack Overflow fikir, deneyim ve hata örnekleri bulmaya yardım eder. İçerikler yayımlanmadan önce birincil kaynaklarla doğrulanmalı; kişisel görüş, resmi bilgi gibi işaretlenmemeli.</p></section></div>`}
function githubView(){return `${heading('GITHUB PRATİĞİ','Ekipte kodu nasıl güvenle teslim edersin?','Commit ve branch’ten GitHub Actions’a: kavramı oku, senaryoda uygula, sonra kendi repo akışına taşı.')}<div class="source-note"><strong>Kaynak:</strong> Git’in resmi dokümantasyonu ve GitHub Docs/Changelog. Workflow davranışları değişebileceği için güncel sözdizimi kaynak sayfasından kontrol edilir.</div><div class="github-grid">${[['01 · GIT','Branch ve commit','Değişiklikleri küçük, anlamlı parçalara ayır.'],['02 · COLLABORATION','Pull request','Değişikliği incelet, tartış ve test sonuçlarını kontrol et.'],['03 · HATA','Merge conflict','İki değişiklik aynı satırları etkileyince kanıtla çöz.'],['04 · AUTOMATION','GitHub Actions','Workflow YAML ile build ve test adımlarını otomatikleştir.'],['05 · SECURITY','GITHUB_TOKEN','Workflow’a gereken en az izinleri ver.'],['06 · DEBUG','Kırmızı workflow','Başarısız job, step, log ve artefact’ı sırasıyla incele.']].map(x=>`<article class="practice-tile" data-action="${x[0].includes('HATA')?'goto-errors':'github-lesson'}"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="section-label">Örnek: Actions güncellemesi</div><article class="news-card"><div class="news-card-top"><span class="source-badge">Resmi changelog</span><span>3 Eylül 2026</span></div><h3>Runner sürüm sonunu izleme ve vulnerability-alerts token izni</h3><p>Bu changelog kaydı, runner sürüm deprecations bilgisi için API ve GITHUB_TOKEN'a yeni salt okunur izin eklenmesini anlatıyor.</p><div class="news-actions">${link(sources.github,'GitHub Changelog kaynağı')}</div></article>`}
const renderers={today,quiz:quizView,map:mapView,errors:errorsView,concepts:conceptsView,news:newsView,github:githubView};
function render(){const view=state.view;root.innerHTML=(renderers[view]||today)();const names={advanced:window.realdevLocale==='en'?'Advanced practice':'İleri eğitim',interview:window.realdevLocale==='en'?'Interviews and projects':'Mülakat ve projeler',today:'Bugün',quiz:'Beceri taraması',map:'Beceri haritam',errors:'Hata laboratuvarı',concepts:'Kavramlar',news:'Yazılım haberleri',github:'GitHub pratiği',route:'Çalışma rotam',history:'Cevap geçmişim',topics:'Konu ara',notes:'Notlarım',account:'Hesabım',lab:'Kod alanı',codehistory:'Kod geçmişim',library:'Kütüphanem',review:'Soruyu tekrar incele'};document.getElementById('crumbCurrent').textContent=names[view]||'Bugün';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view||(view==='quiz'&&b.dataset.view==='today')))}
function go(view){state.view=view;state.quizMode=false;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0)}
document.addEventListener('input',e=>{if(e.target.id!=='conceptSearch')return;const terms=e.target.value.toLocaleLowerCase('tr-TR').trim().split(/\s+/).filter(Boolean);let visible=0;document.querySelectorAll('.concept-card').forEach(card=>{const text=card.textContent.toLocaleLowerCase('tr-TR');const show=terms.every(term=>text.includes(term));card.hidden=!show;if(show)visible++});const count=document.getElementById('conceptSearchCount');if(count)count.textContent=`${visible} kavram`;});
document.addEventListener('click',e=>{const viewButton=e.target.closest('[data-view]');if(viewButton){go(viewButton.dataset.view);return}const choice=e.target.closest('[data-choice]');if(choice&&!state.answered){state.selected=Number(choice.dataset.choice);state.answered=true;if(state.selected===quiz[state.quizIndex].answer)state.completed++;save();render();return}const concept=e.target.closest('[data-concept]');if(concept){state.conceptOpen=concept.dataset.concept;render();document.querySelector('.concept-detail')?.scrollIntoView({behavior:'smooth',block:'center'});return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'start-quiz':state.view='quiz';state.quizMode=true;state.quizIndex=0;state.selected=null;state.answered=false;render();break;case'next-quiz':state.quizIndex++;state.selected=null;state.answered=false;if(state.quizIndex>=quiz.length){state.view='quiz';state.quizMode=true}render();break;case'dont-know':state.selected=-1;state.answered=true;render();break;case'reset-quiz':state.quizIndex=0;state.selected=null;state.answered=false;render();break;case'hint':state.errorHint++;render();break;case'check-error':state.answerText=document.getElementById('errorAnswer').value.trim();if(!state.answerText){toast('Önce teşhis düşünceni yaz veya sesli anlat.');break}state.errorSolved=true;save();render();break;case'mic':startSpeech(a.dataset.target||'errorAnswer');break;case'check-concept':conceptFeedback();break;case'summary':{const i=Number(a.dataset.index);state.newsSummaries[i]=!state.newsSummaries[i];render();break}case'coming-error':toast('Bu senaryo ilk sürümde yakında eklenecek.');break;case'github-lesson':toast('Bu çalışma kartı sıradaki geliştirme adımında.');break;case'goto-errors':go('errors');break}});
function startSpeech(targetId){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Bu tarayıcı sesli yazmayı desteklemiyor. Yazılı yanıtı kullanabilirsin.');return}const r=new Speech();r.lang=window.realdevLocale==='en'?'en-US':'tr-TR';r.interimResults=false;r.onresult=ev=>{const el=document.getElementById(targetId);if(el){el.value+=(el.value?' ':'')+ev.results[0][0].transcript;state.answerText=el.value}};r.onerror=()=>toast('Ses tanınamadı. İstersen yazılı yanıt verebilirsin.');r.start();toast(window.realdevLocale==='en'?'Listening… explain in English.':'Dinliyorum… Türkçe açıklamanı yap.');}
function conceptFeedback(){const input=document.getElementById('conceptAnswer')?.value.trim();const box=document.getElementById('conceptFeedback');if(!input){box.innerHTML='<div class="result-box warning">Önce kendi cümlenle kısa bir açıklama yaz.</div>';return}const words=input.split(/\s+/).length;box.innerHTML=`<div class="result-box ${words<12?'warning':''}"><h4>${words<12?'Biraz daha açmayı dene.':'İyi bir başlangıç.'}</h4>${words<12?'Açıklamana ne işe yaradığını ve nerede kullanıldığını ekle.':'Açıklamanı kendin oluşturdun. Şimdi kaynak anlatımıyla karşılaştır: hangi noktayı eklerdin?'} Otomatik teknik doğruluk puanı vermiyoruz; bu prototip yanıtını sunucuya göndermiyor.</div>`;}
document.getElementById('menuButton').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
function profile(){const goal=document.getElementById('dailyGoal');goal.value=localStorage.getItem('realdev-daily-goal')||'15 dakika';const selected=JSON.parse(localStorage.getItem('realdev-goals')||'["Full stack","Oyun geliştirme"]');document.querySelectorAll('#goalOptions input').forEach(input=>input.checked=selected.includes(input.value));document.getElementById('profileDialog').showModal()};document.getElementById('profileOpen').addEventListener('click',profile);document.getElementById('profileOpenTop').addEventListener('click',profile);document.getElementById('saveProfile').addEventListener('click',()=>{const goals=[...document.querySelectorAll('#goalOptions input:checked')].map(input=>input.value);if(!goals.length){toast('En az bir öğrenme hedefi seç.');return}localStorage.setItem('realdev-daily-goal',document.getElementById('dailyGoal').value);localStorage.setItem('realdev-goals',JSON.stringify(goals));document.getElementById('goalSubtitle').textContent=goals.join(' · ');document.getElementById('profileDialog').close();toast('Hedeflerin ve günlük süren bu cihazda kaydedildi.')});document.getElementById('reminderButton').addEventListener('click',()=>window.realdevReminders?.());
render();


